const buttonClasses = {
  primary: "bg-blue-700 text-white hover:bg-blue-800",
  quiet: "bg-slate-100 text-slate-900 hover:bg-slate-200",
};

function ActionButton({ variant = "primary", children }) {
  return <button className={`rounded-lg px-4 py-2 ${buttonClasses[variant]}`}>{children}</button>;
}
